dashboard.definition:
{
 "title": "Incident Timeline",
 "description": "One incident, step by step: what connected, what Isovalent observed, what Splunk decided, what was enforced and the proof. Pick the incident at the top; the newest is selected by default",
 "inputs": {
  "input_incident": {
   "type": "input.dropdown",
   "title": "Incident (newest first)",
   "dataSources": {
    "primary": "ds_incidents"
   },
   "options": {
    "items": "> frame(label, value) | prepend(formattedStatics) | objects()",
    "token": "incident",
    "selectFirstSearchResult": true
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "-24h",
      "latest": "now"
     }
    }
   }
  }
 },
 "visualizations": {
  "viz_step1": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### $ds_step1:result.mark$ $ds_step1:result.title$\n\n$ds_step1:result.line1$\n\n$ds_step1:result.line2$\n\n$ds_step1:result.line3$"
   },
   "dataSources": {
    "primary": "ds_step1"
   }
  },
  "viz_step2": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### $ds_step2:result.mark$ $ds_step2:result.title$\n\n$ds_step2:result.line1$\n\n$ds_step2:result.line2$\n\n$ds_step2:result.line3$"
   },
   "dataSources": {
    "primary": "ds_step2"
   }
  },
  "viz_step3": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### $ds_step3:result.mark$ $ds_step3:result.title$\n\n$ds_step3:result.line1$\n\n$ds_step3:result.line2$\n\n$ds_step3:result.line3$"
   },
   "dataSources": {
    "primary": "ds_step3"
   }
  },
  "viz_step4": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### $ds_step4:result.mark$ $ds_step4:result.title$\n\n$ds_step4:result.line1$\n\n$ds_step4:result.line2$\n\n$ds_step4:result.line3$"
   },
   "dataSources": {
    "primary": "ds_step4"
   }
  },
  "viz_step5": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### $ds_step5:result.mark$ $ds_step5:result.title$\n\n$ds_step5:result.line1$\n\n$ds_step5:result.line2$\n\n$ds_step5:result.line3$"
   },
   "dataSources": {
    "primary": "ds_step5"
   }
  },
  "viz_grid_title": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**One incident, end to end**",
    "fontColor": "#8C9BA5"
   }
  },
  "viz_grid_h1": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 1 Connect"
   }
  },
  "viz_grid_h2": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 2 Observe"
   }
  },
  "viz_grid_h3": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 3 Decide"
   }
  },
  "viz_grid_h4": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 4 Enforce"
   }
  },
  "viz_grid_h5": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 5 Verify"
   }
  },
  "viz_lane1": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Workloads**\n\nBuild farm, AI training",
    "fontColor": "#FFFFFF",
    "fontSize": "small"
   }
  },
  "viz_lane2": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Cisco Isovalent**\n\nCilium · Hubble · Tetragon",
    "fontColor": "#009CEB",
    "fontSize": "small"
   }
  },
  "viz_lane3": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Splunk platform**\n\nIngest · correlate · posture",
    "fontColor": "#CB2196",
    "fontSize": "small"
   }
  },
  "viz_lane4": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Enterprise Security**\n\nRisk-based alerting",
    "fontColor": "#CB2196",
    "fontSize": "small"
   }
  },
  "viz_lane5": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Agent Launchpad**\n\nNo-code agent",
    "fontColor": "#CB2196",
    "fontSize": "small"
   }
  },
  "viz_lane6": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**SOAR and people**\n\nPlaybook · approval",
    "fontColor": "#CB2196",
    "fontSize": "small"
   }
  },
  "viz_cell1": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**CI runner connects**\n\nJob 88213 → checkpoint store :9000\n\n$ds_grid:result.cell1_mark$ $ds_grid:result.cell1_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20sourcetype%3Dcisco%3Aisovalent%3AprocessConnect%20src_pod%3D%22ci-runner-7d9f8-xk2lq%22%20dest_protected%3Dtrue%20%7C%20table%20_time%20process%20parent_process%20src_pod%20dest_pod%20dest_workload%20dest_port&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell2": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Isovalent observes**\n\nHubble: AUDIT (would deny) · Tetragon: curl from postbuild.sh\n\n$ds_grid:result.cell2_mark$ $ds_grid:result.cell2_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20sourcetype%3Dcilium%3Ahubble%3Aflow%20src_pod%3D%22ci-runner-7d9f8-xk2lq%22%20verdict%3DAUDIT%20%7C%20table%20_time%20verdict%20traffic_direction%20src_identity%20dest_identity%20node%20policy_match_type&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell3": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Events land**\n\nzero_trust index, seconds after the connection\n\n$ds_grid:result.cell3_mark$ $ds_grid:result.cell3_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20%28src_pod%3D%22ci-runner-7d9f8-xk2lq%22%20OR%20pod%3D%22ci-runner-7d9f8-xk2lq%22%29%20%7C%20eval%20lag%3D_indextime-_time%20%7C%20stats%20count%20min%28_time%29%20as%20first_event%20max%28lag%29%20as%20max_lag_s%20avg%28lag%29%20as%20avg_lag_s%20by%20sourcetype&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell4": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Splunk correlates**\n\nTwo risk signals (50 + 40) tie the flow to the workload, CI job 88213 and bf-node-03\n\n$ds_grid:result.cell4_mark$ $ds_grid:result.cell4_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Drisk%20$incident$%20source%3D%22ZT%20-%20%2A%22%20risk_object%3D%22build-farm%2Fci-runner%22%20%7C%20table%20_time%20source%20risk_score%20threat_object%20risk_message&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell5": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Finding group**\n\n$ds_grid:result.finding_line$\n\n$ds_grid:result.cell5_mark$ $ds_grid:result.cell5_time$ · [evidence](/app/zt_incident_demo/search?q=search%20$incident$%20%60notable%60%20%7C%20search%20source%3D%22ZT%20-%20Workload%20Exceeded%20Risk%20Threshold%20on%20Protected-Path%20Signals%20-%20Rule%22%20%7C%20eval%20rule_title%3Dcoalesce%28orig_rule_title%2C%20rule_title%29%20%7C%20table%20_time%20event_id%20rule_title%20risk_score%20source_count%20threat_object%20annotations.mitre_attack.mitre_technique_id&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell6": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Agent brief**\n\nTrue positive · recommends the kernel quarantine\n\n$ds_grid:result.cell6_mark$ $ds_grid:result.cell6_time$ · [evidence](/app/zt_incident_demo/search?q=%7C%20inputlookup%20zt_agent_briefs_lookup%20%7C%20%60zt_incident_window%28%22$incident$%22%29%60%20%7C%20where%20run_epoch%3E%3Dzt_s%20AND%20run_epoch%3C%3Dzt_e%20%7C%20sort%20-%20run_epoch%20%7C%20head%201%20%7C%20eval%20brief_at%3Dstrftime%28run_epoch%2C%22%25Y-%25m-%25d%20%25H%3A%25M%3A%25S%22%29%20%7C%20table%20brief_at%20investigation_id%20finding_id%20disposition%20confidence%20enforcement_point%20action%20policy_name%20approver_labels%20brief_text&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell7": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Approve and apply**\n\nj.chen (SOC tier 2) approves · CiliumNetworkPolicy applied\n\n$ds_grid:result.cell7_mark$ $ds_grid:result.cell7_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20sourcetype%3Dzt%3Aenforcement%3Aaudit%20state%20IN%20%28%22requested%22%2C%22approved%22%2C%22rejected%22%2C%22refused%22%2C%22applied%22%29%20%7C%20table%20_time%20state%20request_id%20action%20policy_name%20approved_by_label%20executed_by%20comment%20status&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell8": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Cilium enforces**\n\nQuarantine policy isolates the pod in the kernel\n\n$ds_grid:result.cell8_mark$ $ds_grid:result.cell8_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20sourcetype%3Dkube%3Aapiserver%3Aaudit%20k8s_user%3D%22system%3Aserviceaccount%3Asoar%3Azt-enforcer%22%20%7C%20table%20_time%20k8s_verb%20k8s_resource%20k8s_namespace%20k8s_name%20status_code%20audit_id&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell9": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Runner isolated**\n\nPod labelled quarantined · the rest of the build farm keeps running\n\n$ds_grid:result.cell9_mark$ $ds_grid:result.cell9_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20sourcetype%3Dcilium%3Ahubble%3Aflow%20src_workload%3D%22build-farm%2F%2A%22%20%7C%20eval%20state%3Dif%28src_pod%3D%22ci-runner-7d9f8-xk2lq%22%2C%22quarantined%20runner%22%2C%22rest%20of%20the%20build%20farm%22%29%20%7C%20stats%20count%20by%20state%20verdict&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell10": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Retries dropped**\n\nDROPPED by the quarantine policy, new identity 48291\n\n$ds_grid:result.cell10_mark$ $ds_grid:result.cell10_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20sourcetype%3Dcilium%3Ahubble%3Aflow%20src_pod%3D%22ci-runner-7d9f8-xk2lq%22%20verdict%3DDROPPED%20%7C%20table%20_time%20src_identity%20dest_identity%20node%20policy_denied%20drop_reason&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell11": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Posture improves**\n\n$ds_grid:result.posture_line$\n\n$ds_grid:result.cell11_mark$ $ds_grid:result.cell11_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzt_summary%20source%3D%22ZT%20Posture%20-%20Rollup%22%20%5B%7C%20makeresults%20%7C%20%60zt_incident_window%28%22$incident$%22%29%60%20%7C%20eval%20earliest%3Dzt_s-3600%2C%20latest%3Dzt_e%20%7C%20fields%20earliest%20latest%20%7C%20return%20earliest%20latest%5D%20%7C%20table%20_time%20coverage_pct%20unprotected%20enforced%20paths%20enforcement_24h%20identities%20%7C%20sort%20-%20_time&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_cell12": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "**Audit trail**\n\nWho approved, what changed, when · request verified\n\n$ds_grid:result.cell12_mark$ $ds_grid:result.cell12_time$ · [evidence](/app/zt_incident_demo/search?q=search%20index%3Dzero_trust%20$incident$%20sourcetype%3Dzt%3Aenforcement%3Aaudit%20%7C%20table%20_time%20state%20request_id%20finding_id%20investigation_id%20action%20policy_name%20approved_by_label%20executed_by%20k8s_audit_id%20status&earliest=-30d&latest=now)",
    "backgroundColor": "#1A2837",
    "fontSize": "small"
   },
   "dataSources": {
    "primary": "ds_grid"
   }
  },
  "viz_gdi_hubble": {
   "type": "splunk.singlevalue",
   "title": "Hubble flows (24h)",
   "description": "over HTTP Event Collector",
   "dataSources": {
    "primary": "ds_gdi_hubble"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"count\") | lastPoint()",
    "majorColor": "#009CEB",
    "majorFontSize": 48,
    "shouldUseThousandSeparators": true,
    "underLabel": "$ds_gdi_hubble:result.age_label$",
    "underLabelFontSize": 14,
    "sparklineDisplay": "off",
    "trendDisplay": "off"
   }
  },
  "viz_gdi_tetragon": {
   "type": "splunk.singlevalue",
   "title": "Tetragon events (24h)",
   "description": "Cisco Security Cloud App sourcetypes",
   "dataSources": {
    "primary": "ds_gdi_tetragon"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"count\") | lastPoint()",
    "majorColor": "#00CDAF",
    "majorFontSize": 48,
    "shouldUseThousandSeparators": true,
    "underLabel": "$ds_gdi_tetragon:result.age_label$",
    "underLabelFontSize": 14,
    "sparklineDisplay": "off",
    "trendDisplay": "off"
   }
  },
  "viz_gdi_nexus": {
   "type": "splunk.singlevalue",
   "title": "Nexus switch data (24h)",
   "description": "cisco:nexus:endpoint, cisco:nexus:config",
   "dataSources": {
    "primary": "ds_gdi_nexus"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"count\") | lastPoint()",
    "majorColor": "#7B56DB",
    "majorFontSize": 48,
    "shouldUseThousandSeparators": true,
    "underLabel": "$ds_gdi_nexus:result.age_label$",
    "underLabelFontSize": 14,
    "sparklineDisplay": "off",
    "trendDisplay": "off"
   }
  },
  "viz_gdi_liveprotect": {
   "type": "splunk.singlevalue",
   "title": "Live Protect (24h)",
   "description": "cisco:nexus:liveprotect",
   "dataSources": {
    "primary": "ds_gdi_liveprotect"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"count\") | lastPoint()",
    "majorColor": "#DD9900",
    "majorFontSize": 48,
    "shouldUseThousandSeparators": true,
    "underLabel": "$ds_gdi_liveprotect:result.age_label$",
    "underLabelFontSize": 14,
    "sparklineDisplay": "off",
    "trendDisplay": "off"
   }
  },
  "viz_raw_audit": {
   "type": "splunk.table",
   "title": "Hubble flow: first AUDIT at the store (raw JSON)",
   "dataSources": {
    "primary": "ds_raw_audit"
   },
   "options": {
    "count": 1,
    "headerVisibility": "none",
    "font": "monospace",
    "fontSize": "small",
    "columnFormat": {
     "_raw": {
      "textOverflow": "anywhere"
     }
    }
   },
   "hideWhenNoData": true
  },
  "viz_raw_audit_empty": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "\n\n### No incident yet\n\nThe first Hubble AUDIT flow from the runner to the checkpoint store appears here as raw JSON."
   },
   "title": "Hubble flow: first AUDIT at the store (raw JSON)"
  },
  "viz_raw_tetragon": {
   "type": "splunk.table",
   "title": "Tetragon: the program behind the connection (raw JSON)",
   "dataSources": {
    "primary": "ds_raw_tetragon"
   },
   "options": {
    "count": 1,
    "headerVisibility": "none",
    "font": "monospace",
    "fontSize": "small",
    "columnFormat": {
     "_raw": {
      "textOverflow": "anywhere"
     }
    }
   },
   "hideWhenNoData": true
  },
  "viz_raw_tetragon_empty": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "\n\n### No incident yet\n\nThe Tetragon connect event naming the program behind the connection appears here as raw JSON."
   },
   "title": "Tetragon: the program behind the connection (raw JSON)"
  },
  "viz_brief": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "$ds_brief:result.brief_md$"
   },
   "title": "Agent brief (ZTFlowInvestigator)",
   "dataSources": {
    "primary": "ds_brief"
   }
  },
  "viz_incident_events": {
   "type": "splunk.table",
   "title": "Every event of the selected incident",
   "description": "Click a row to open the raw event in search",
   "dataSources": {
    "primary": "ds_incident"
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "custom",
      "query": "index=zero_trust $incident$ sourcetype=\"$row.sourcetype.value$\" (src_pod=\"ci-runner-7d9f8-xk2lq\" OR pod=\"ci-runner-7d9f8-xk2lq\" OR build_id=88213 OR sourcetype=zt:enforcement:audit OR k8s_user=\"system:serviceaccount:soar:zt-enforcer\") | where abs(_time - coalesce(strptime(\"$row._time.value$\", \"%Y-%m-%dT%H:%M:%S.%3Q%:z\"), strptime(\"$row._time.value$\", \"%Y-%m-%dT%H:%M:%S%:z\"))) < 1",
      "earliest": "-30d",
      "latest": "now",
      "newTab": true
     }
    }
   ],
   "context": {
    "timeConfig": {
     "time": {
      "format": "MM-DD HH:mm:ss"
     }
    },
    "stepColorConfig": [
     {
      "match": "1 Connect",
      "value": "#7B56DB"
     },
     {
      "match": "2 Observe",
      "value": "#009CEB"
     },
     {
      "match": "3 Decide",
      "value": "#00CDAF"
     },
     {
      "match": "4 Enforce",
      "value": "#DD9900"
     },
     {
      "match": "5 Verify",
      "value": "#FF677B"
     }
    ]
   },
   "options": {
    "count": 20,
    "columnFormat": {
     "_time": {
      "data": "> table | seriesByName(\"_time\") | formatByType(timeConfig)"
     },
     "step": {
      "rowColors": "> table | seriesByName(\"step\") | matchValue(stepColorConfig)"
     },
     "summary": {
      "textOverflow": "anywhere"
     }
    }
   },
   "hideWhenNoData": true
  },
  "viz_incident_empty": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "\n\n### No incident yet\n\nEvery event of the incident (CI job, Hubble flows, Tetragon events, enforcement audit trail, Kubernetes API audit) is listed here with its step once the incident starts."
   },
   "title": "Every event of the selected incident"
  }
 },
 "dataSources": {
  "ds_step1": {
   "type": "ds.search",
   "name": "ds_step1",
   "options": {
